func fill(n: int) -> int[]:
    mut out: int[] = []
    for i in range(n):
        out.append(i * i)
    return out

func main() -> int:
    const squares = fill(10)
    mut copy = squares.copy()
    copy.append(1)
    return len(squares) + len(copy)

