func batch(size: int) -> int:
    mut scratch: str[] = []
    for index in range(size):
        scratch.append(f"item {index}")
    return len(scratch)

func main() -> int:
    mut kept: int[] = []
    for step in range(50):
        kept.append(batch(step))
    mut total = 0
    for value in kept:
        total += value
    return total

